/* Version A */
class Account {
  calculateFee(amount) {
    const base = this.baseFee(amount);
    return base + this.extraFee(amount);
  }
  baseFee(amount) { return amount * 0.01; }
  extraFee(amount) { return 0; }
}

class PremiumAccount extends Account {
  extraFee(amount) { return amount * 0.005; }
}

/* Version B */
class AccountV2 {
  calculateFee(amount, type) {
    if (type === 'premium') return amount * 0.015;
    return amount * 0.01;
  }
}

class PremiumAccountV2 extends AccountV2 {
  // no override available for parts of algorithm
}
